To better understand the conditions of Proposition \ref{procofinality}, it is natural to consider the fibrations $\pi_{\cal C}^{F}:(1_{\cal C}\downarrow F)\to {\cal C}$ and $\pi^{F'}_{\cal C}:(1_{\cal C}\downarrow F)\to {\cal C}$ given by the canonical projection functors (cf. section \ref{sec:fibrgenelements} for an analysis of this type of fibrations). Then the natural transformation $\alpha$ yields a functor $\alpha_{\textup{fib}}: (1_{\cal C}\downarrow F) \to (1_{\cal C}\downarrow F')$, sending to each object $(c, a, x:c\to F(a))$ of $(1_{\cal C}\downarrow F)$ the object $(c, \xi(a), \alpha(a)\circ x:c\to F'(\xi(a)))$ of $(1_{\cal C}\downarrow F')$, which is actually a morphisms of fibrations.  

\begin{remarks}\label{rempropcofinality}
	\begin{enumerate}[(a)]
		\item Condition (i) of Proposition \ref{procofinality} can be replaced by the single condition that for any object $u:=(c, a', y:c\to F'(a'))$ of the category $(1_{\cal C}\downarrow F')$, there is a $J$-covering family such that the category $((u\circ f_{i})\downarrow \alpha_{\textup{fib}})$ is non-empty for each $i\in I$.

		\item In condition (i) of Proposition \ref{procofinality}, if the claim is satisfied for an arrow $y:d\to F(a')$ then it is satisfied by any arrow of the form $y\circ z$ for an arrow $z$ composable with $y$. It follows in particular that if $\xi$ is essentially surjective and $\alpha$ is the identity then the condition is satisfied.

		\item Proposition \ref{procofinality} can be notably applied in the context of colimit-preserving functors $$Z:\Sh({\cal C}, J)\to \Sh({\cal D}, K)$$ between Grothendieck toposes such that $Z\circ l=l'\circ z$ for some functor $z:{\cal C}\to {\cal D}$ (such as, for instance, inverse image functors of geometric morphisms induced by a morphism of sites, or essential images of essential geometric morphisms induced by a continuous comorphism of sites, as investigated in section \ref{sec:essentialmorphismsandcomorphisms}). Indeed, the value of such a functor $Z$ on a $J$-sheaf $Q$ on $\cal C$ is given by $\textup{colim}_{\Sh({\cal D}, K)}(Z\circ l \circ \pi_{Q})=\textup{colim}_{\Sh({\cal D}, K)}(l'\circ z \circ \pi_{Q})$, where $\pi_{Q}:{\int Q} \to {\cal C}$ is the canonical projection functor from the category $\int Q$ of elements of $Q$. See section \ref{sec:locallyconnectedmorphisms} below for an application of this remark. 

		\item We shall see in section \ref{sec:essentialmorphismsandcomorphisms} (cf. Proposition \ref{propcofinalcontinuous}) that, under the hypotheses of Proposition \ref{procofinality}, if $p$ is a continuous comorphism of sites $({\cal C}, J)\to ({\cal D}, K)$ such that the essential image of the associated geometric morphism $C_{p}$ is conservative then $(\xi, \alpha)$ satisfies the conditions of Proposition \ref{procofinality} if and only if $(\xi, p\alpha)$ does.
	\end{enumerate}
\end{remarks}


Let us now apply Proposition \ref{procofinality} in two notable cases:
\begin{enumerate}[(1)]
	\item $F=\xi:{\cal A}\to {\cal C}$, $F'=1_{\cal C}$, $\alpha$ is the identity. In this case the equivalence relations $R'_{c}$ are the total relations, and the proposition yields the following criterion: the canonical arrow
	\[
	\textup{colim}_{[{\cal C}^{\textup{op}}, \Set]}(y_{\cal C}\circ \xi) \to \textup{colim}_{[{\cal C}^{\textup{op}}, \Set]}(y_{\cal C})=1_{[{\cal C}^{\textup{op}}, \Set]}
	\]
	is sent by $a_{J}$ to an isomorphism
	\[
	\textup{colim}_{\Sh({\cal C}, J)}(l\circ \xi) \to 1_{\Sh({\cal C}, J)}
	\]
	if and only if the following conditions are satisfied:
	\begin{enumerate}[(i)]
		\item For any object $c$ of $\cal C$ there are a $J$-covering family $\{f_i: c_i \to c \mid i\in I\}$ and for each $i\in I$ an object $a_{i}$ of $\cal A$ and an arrow $y_i:c_{i}\to F(a_{i})$.

		\item For any object $c$ of $\cal C$ and any arrows $x:c\to F(a)$ and $x':c\to F(b)$ in $\cal C$, there is a $J$-covering family $\{f_i: c_i \to c \mid i\in I\}$ such that $(x\circ f_i, x'\circ f_i)\in R_{c_{i}}$ for each $i\in I$. 
	\end{enumerate}	

	Notice that if $J$ is the trivial Grothendieck topology then the above conditions amount precisely to the requirement that for every object $c$ of $\cal C$, the category $(c\downarrow \xi)$ be non-empty and connected, which means precisely that the functor $F$ is cofinal (in the classical sense). It is therefore natural to call \emph{$J$-cofinal} a functor $F:{\cal A}\to {\cal C}$ which satisfies the two conditions above (see Definition \ref{defrelcofinality} below). 

	\item $F'$ is the forgetful functor $U_{c_{0}}:{\cal C}\slash c_{0}\to {\cal C}$ for an object $c_{0}$ of $\cal C$, $\xi$ is a cocone $\{\xi_{a}: F(a)\to c_{0} \mid a\in {\cal A}\}$ under the functor $F$ with vertex $c_{0}$ and $\alpha$ is the identity. In this case we have: for any $y:c \to (U_{c_{0}}([p:c'\to c_{0}]))$ and $y':c \to (U_{c_{0}}([q:c''\to c_{0}]))$, $(y, y')\in R'_{c}$ if and only if $p\circ y=q\circ y'$. So the proposition yields the following criterion: the cocone $\xi$ is sent by the canonical functor ${\cal C}\to \Sh({\cal C}, J)$ to a colimit if and only if the following conditions are satisfied:
	\begin{enumerate}[(i)]
		\item For any object $c$ of $\cal C$ and any arrow $y:c\to c_{0}$ in $\cal C$ there are a $J$-covering family $\{f_i: c_i \to c \mid i\in I\}$ and for each $i\in I$ an object $a_{i}$ of $\cal A$ and an arrow $y_i:c_{i}\to F(a_{i})$ such that $y\circ f_{i}=\xi_{a_{i}}\circ y_{i}$.

		\item For any object $c$ of $\cal C$ and any arrows $x:c\to F(a)$ and $x':c\to F(b)$ in $\cal C$ such that $\xi_{a}\circ x= \xi_{b}\circ x'$ there is a $J$-covering family $\{f_i: c_i \to c \mid i\in I\}$ such that $(x\circ f_i, x'\circ f_i)\in R_{c_{i}}$ for each $i\in I$. 
	\end{enumerate}	 
\end{enumerate}


\begin{definition}\label{defrelcofinality}
	Given a small site $({\cal C}, J)$, a functor $F:{\cal A}\to {\cal C}$ is said to be \emph{$J$-cofinal} if the following conditions are satisfied:
	\begin{enumerate}[(i)]
		\item For any object $c$ of $\cal C$ there are a $J$-covering family $\{f_i: c_i \to c \mid i\in I\}$ and for each $i\in I$ an object $a_{i}$ of $\cal A$ and an arrow $y_i:c_{i}\to F(a_{i})$.

		\item For any object $c$ of $\cal C$ and any arrows $x:c\to F(a)$ and $x':c\to F(b)$ in $\cal C$ there is a $J$-covering family $\{f_i: c_i \to c \mid i\in I\}$ such that $x\circ f_i$ and $x'\circ f_i$ belong to the same connected component of the category $(c_i \downarrow F)$ for each $i\in I$. 
	\end{enumerate}		
\end{definition}

