	C(d') \ar[ur, "u"] \ar[dr, "v\quad"{below}]   &   &  C(A(c))              \\
	& C(A(\dom(s))) \ar[uu, "\quad\quad\quad C(A(t))"{below}]  \ar[ur, "\quad\quad\quad C(A(s))"{below}] & 
