	\end{equation*} 

	So in both cases we have a lift of the connection between the objects $(r:\dom(r)\to c, u:C(d')\to C(A(\dom(r))))$ and $(s:\dom(s)\to c, v:C(d')\to C(A(\dom(s))))$ from the category $D^{C\circ A}_{S}$ to the category $D^{A}_{S}$.

	So our zig-zag can be lifted to a zig-zag connecting the objects $(f_{c}:\dom(f_{c})\to c, A(f_{v})\circ \alpha:d\to A(\dom(f_{c})))$ and $(g_{c}:\dom(g_{c})\to c, A(g_{v})\circ \beta:d\to A(\dom(g_{c})))$, and hence between the objects $(f:\dom(f_{c})\to c, \alpha:d\to A(c'))$ and $(g:c''\to c, \beta:d\to A(c''))$, since $(f_{c}:\dom(f_{c})\to c, A(f_{v})\circ \alpha:d\to A(\dom(f_{c})))$ (resp. $(g_{c}:\dom(g_{c})\to c, A(g_{v})\circ \beta:d\to A(\dom(g_{c})))$) is in the same connected component as $(f:\dom(f_{c})\to c, \alpha:d\to A(c'))$ (resp. $(g:c''\to c, \beta:d\to A(c''))$).   

	The last statement of (iii) follows from (ii), since every morphism of fibrations sends cartesian arrows to cartesian arrows and vertical arrows to vertical arrows. 
\end{proofs}

