The following technical result about morphisms of fibrations will be instrumental in the next section, for proving that such morphisms induce locally connected morphisms of toposes:

\begin{proofs}
	(i) From the fact that the canonical indexing of a Grothendieck topos over itself is a stack with respect to the canonical topology it follows that the square
	\[
	\xymatrix{
	{\cal F}\slash f^{\ast}(B) \ar[rr]^{(f\slash B)_{!}} \ar[d]^{(f^{\ast}(h))^{\ast}} & &  {\cal E}\slash B    \ar[d]^{h^{\ast}} \\
	{\cal F}\slash f^{\ast}(A) \ar[rr]^{(f\slash A)_{!}} & & {\cal E}\slash A
	} 
	\]
	commutes if and only if each of the outer rectangles
	\[
	\xymatrix{
	{\cal F}\slash f^{\ast}(B) \ar[rr]^{(f\slash B)_{!}} \ar[d]^{(f^{\ast}(h))^{\ast}} & &  {\cal E}\slash B    \ar[d]^{h^{\ast}} \\
	{\cal F}\slash f^{\ast}(A) \ar[rr]^{(f\slash A)_{!}} \ar[d]^{(f^{\ast}(f_{i}))^{\ast}} & & {\cal E}\slash A \ar[d]^{f_{i}^{\ast}}\\
	{\cal F}\slash f^{\ast}(A_{i}) \ar[rr]^{(f\slash A_{i})_{!}} & & {\cal E}\slash A_{i}
	} 
	\]
	does. But this rectangle is precisely the square corresponding to the arrow $h\circ f_{i}$. This shows that the commutativity of the square with respect to an arrow $h$ is equivalent to that of all the squares with respect to the arrows of the form $h\circ f_{i}$ for $i\in I$.

	(ii) Let us preliminarily notice that, for any epimorphic family $\{c_{k}:C_{k}\to C \mid k\in K\}$ in a Grothendieck topos $\cal E$, the family of functors $\{\Sigma^{\cal E}_{c_{k}}:{\cal E}\slash C_{k} \to {\cal E}\slash C\}$ satisfies the property that for any two colimit-preserving functors $H, K:{\cal E}\slash C \to {\cal F}$, there are isomorphisms $H\circ \Sigma^{\cal E}_{c_{k}}\cong K\circ \Sigma^{\cal E}_{c_{k}}$ satisfying the obvious coherence relations if and only if $H\cong K$. Indeed, for any object $[u:U\to C]$ of ${\cal E}\slash C$, consider the pullback squares
		\[
	\xymatrix{
		U_{k} \ar[rr]^{\xi_{k}} \ar[d]^{u_{k}} & &  U    \ar[d]^{u} \\
		C_{k} \ar[rr]^{c_{k}} & & C.
	} 
	\]    

	  Since the family $\{\xi_{k}:U_{k} \to U \mid k\in K\}$ is epimorphic, denoting by $S_{u}$ the sieve generated by the family $\{\xi_{k}:U_{k} \to U \mid k\in K\}$, we can represent $[u:U\to C]$ as the colimit in ${\cal E}\slash C$ of the diagram $D_{u}:{\int S}_{u}\to {\cal E}\slash C$ which sends any object $(Z, z:Z\to U)$ of ${\int S_{u}}$ to the object $[u\circ z:Z\to C]$ of ${\cal E}\slash C$. So, for any colimit-preserving functors $H$ and $K$ as above, $H([u])\cong K([u])$ if $H\circ D_{u}\cong K\circ D_{u}$. Now, we have such isomorphisms $H\circ D_{u}\cong K\circ D_{u}$ by the coherence relations existing by our hypotheses between the isomorphisms between the functors $H\circ \Sigma^{\cal E}_{c_{k}}$ and $K\circ \Sigma^{\cal E}_{c_{k}}$. Moreover, these isomorphisms $H([u])\cong K([u])$ (note that any object in the image of $D_{u}$ belongs to the image of some $\Sigma^{\cal E}_{c_{k}}$) are clearly natural in $[u:U\to C]\in {\cal E}\slash C$, which establishes our claim. 

	Now, given, for each $j\in J$, the pullback square
	\[
	\xymatrix{
		A_{j} \ar[rr]^{h_{j}=g_{j}^{\ast}(h)} \ar[d]^{h^{\ast}(g_{j})} & &  B_{j}    \ar[d]^{g_{j}} \\
		A \ar[rr]^{h} & & B,
	} 
	\]
	consider the following cube:  

	\begin{center}
		\begin{tikzcd}[row sep=large, column sep=small]
		& {\cal F}\slash f^{\ast}(B) \arrow[dd, "(f^{\ast}(h))^{\ast}"{yshift=4ex}, rightarrow] \arrow[rr, "(f\slash B)_{!}"] &                                                                             & {\cal E}\slash B \arrow[dd, "h^{\ast}"{yshift=2ex}, rightarrow] \\
		{\cal F}\slash f^{\ast}(B_{j}) \arrow[dd, "(f^{\ast}(h_{j}))^{\ast}"{yshift=2.5ex, xshift=0ex}, rightarrow] \arrow[rr, "(f\slash B_{j})_{!}"{xshift=-4ex}, crossing over] \arrow[ru, "\Sigma^{\cal F}_{f^{\ast}(g_{j})}"] &                                                                                             & {\cal E}\slash B_{j} \arrow[dd, "h_{j}^{\ast}"{yshift=4ex}, rightarrow, crossing over]  \arrow[ru, "\Sigma^{\cal E}_{g_{j}}"] &                                                            \\
		& {\cal F}\slash f^{\ast}(A) \arrow[rr, "(f\slash A)_{!}"{below, xshift=-3ex}]                                                &                                                                             & {\cal E}\slash A                                 \\
		{\cal F}\slash f^{\ast}(A_{j}) \arrow[ru, "\Sigma^{\cal F}_{f^{\ast}(h^{\ast}(g_{j}))}"'] \arrow[rr, "(f\slash A_{j})_{!}"']             &                                                                                             & {\cal E}\slash A_{j} \arrow[ru, "\Sigma^{\cal E}_{h^{\ast}(g_{j})}"']     &                                                           
		\end{tikzcd}
	\end{center} 

We want to show that the back square is commutative (that is, $\Gamma^{f}_{h}$ holds) if and only if the front square is for each $j\in J$ (that is, if and only if $\Gamma^{f}_{g_{j}^{\ast}(h)}$ holds for each $j\in J$). This follows from the above preliminary remark and the fact that all the other squares in the cube commute. More specifically, the lower and upper squares commute since the squares obtained by taking the right adjoints of all functors commute, while the left-hand and right-hand lateral faces commute since they are commutative squares associated with local homeomorphisms of toposes (cf. Remark \ref{remlocallyconnectedcondition}).
\end{proofs}

\begin{remark}\label{remconditionalocallyconnected}
	Condition (a) of Corollary \ref{corlocallyconnectedpresheaf} is satisfied if for any object $(d, z, g)$ of the category ${\cal B}^{y_{\cal D}(h)}_{(c, x)}$ there is an object $(c', y, f)$ of the category ${\cal A}^{y_{\cal D}(h)}_{(c, x)}$ and an arrow $$s:d\to F(c')= a^{y_{\cal D}(h)}_{(c, x)}((c', y, f))$$ such that $z=y\circ s$ and $g=F(f)\circ s$. Note that this condition is always satisfied if $F$ is a fibration (in which case $s$ can be taken to be an isomorphism).
\end{remark}

\begin{proofs}
	As observed in Remark \ref{remconditionalocallyconnected}, condition (a) of Corollary \ref{corlocallyconnectedpresheaf} is satisfied by $F$, so it only remains to show that also condition (b) holds.

	To establish this, we show that any zig-zag connecting two objects $\alpha:d\to a^{y_{\cal D}(h)}_{(c, x)}((a, y, f))=b^{y_{\cal D}(h)}_{(c, x)}((F(a), y, F(f)))=F(a)$ and $\beta:d\to a^{y_{\cal D}(h)}_{(c, x)}((b, y', f'))=b^{y_{\cal D}(h)}_{(c, x)}((F(b), y', F(f')))=F(b)$ in the category $(d\downarrow b^{y_{\cal D}(h)}_{(c, x)})$ can be ` lifted' to a zig-zag connecting them in the category $(d\downarrow a^{y_{\cal D}(h)}_{(c, x)})$. Note that we can suppose without loss of generality the arrows $f$ and $f'$ to be cartesian (at the cost of possibly replacing them with their cartesian images, which does not affect the connected component at which the given object belongs).

	Given an arrow $\delta:d\to a^{y_{\cal D}(h)}_{(c, x)}((a, y, f))=b^{y_{\cal D}(h)}_{(c, x)}((F(a), y, F(f)))=F(a)$ in $\cal D$ and an arrow $\gamma:d \to b^{y_{\cal D}(h)}_{(c, x)}((d', z, g))$ connected to it in the category $(d\downarrow b^{y_{\cal D}(h)}_{(c, x)})$, there are two basic cases:
	\begin{enumerate}[(1)]
		\item There is an arrow $s:(F(a), y, F(f))\to (d', z, g)$ in the category ${\cal B}^{y_{\cal D}(h)}_{(c, x)}$ such that $s\circ \delta=\gamma$; 

		\item There is an arrow $t:(d', z, g) \to (F(a), y, F(f))$ in the category ${\cal B}^{y_{\cal D}(h)}_{(c, x)}$ such that $t\circ \gamma=\delta$. 
	\end{enumerate} 

	Let us show that in each of this cases we can lift this connection to a connection in the category $(d\downarrow a^{y_{\cal D}(h)}_{(c, x)})$.
	\begin{enumerate}
		\item[(1)] Note preliminarily that, since $s:(F(a), y, F(f))\to (d', z, g)$ is an arrow in the category ${\cal B}^{y_{\cal D}(h)}_{(c, x)}$, we have $g\circ s=F(f)$ and $z\circ s=y$. Since $F$ is a fibration, there are an isomorphism $\tau:F(a')\to d'$ and a cartesian arrow $k:a'\to a$ such that $g\circ \tau=F(k)$. Now, since $k$ is cartesian and $F(k)\circ (\tau^{-1}\circ s)=F(f)$, there is a unique arrow $h:a\to a'$ in $\cal C$ such that $F(h)=\tau^{-1}\circ s$ and $k\circ h=f$. Therefore $h$ is an arrow $(a, y, f)\to (a', z\circ \tau, k)$ in the category ${\cal A}^{y_{\cal D}(h)}_{(c, x)}$ which connects $\delta:d\to a^{y_{\cal D}(h)}_{(c, x)}((a, y, f))=F(a)$ with $F(h)\circ \delta:d\to a^{y_{\cal D}(h)}_{(c, x)}((a', z\circ \tau, k))$ and which ` lifts' our given connection in the sense that $F(h)\circ \delta:d\to a^{y_{\cal D}(h)}_{(c, x)}((a', z\circ \tau, k))=b^{y_{\cal D}(h)}_{(c, x)}((F(a'), z\circ \tau, F(k)))$ is isomorphic in the category $(d\downarrow b^{y_{\cal D}(h)}_{(c, x)})$ to the object $\gamma:d \to b^{y_{\cal D}(h)}_{(c, x)}((d', z, g))$. 

		\item[(2)] Note preliminarily that, since $t:(d', z, g)\to (F(a), y, F(f))$ is an arrow in the category ${\cal B}^{y_{\cal D}(h)}_{(c, x)}$, we have $y\circ t=z$ and $F(f)\circ t=g$. Since $F$ is a fibration, there are an object $a''$ of $\cal C$, an isomorphism $\chi:F(a'')\to d'$ and a cartesian arrow $u$ such that $t\circ \chi=F(u)$. Then $t$ is an arrow $(a'', y\circ F(u), f\circ u)\to (a, y, f)$ in the category ${\cal A}^{y_{\cal D}(h)}_{(c, x)}$ which connects $\delta:d\to a^{y_{\cal D}(h)}_{(c, x)}((a, y, f))=F(a)$ with $\chi^{-1}\circ \gamma:d\to a^{y_{\cal D}(h)}_{(c, x)}((a'', y\circ F(u), f\circ u))$ and ` lifts' our given connection in the sense that $\chi^{-1}\circ \gamma:d\to a^{y_{\cal D}(h)}_{(c, x)}((a'', y\circ F(u), f\circ u))=a^{y_{\cal D}(h)}_{(c, x)}((F(a''), y\circ F(u), F(f\circ u)))$ is isomorphic in the category $(d\downarrow b^{y_{\cal D}(h)}_{(c, x)})$ to the object $\gamma:d \to b^{y_{\cal D}(h)}_{(c, x)}((d', z, g))$.    
	\end{enumerate}

	Note that all the ` lifts' constructed in this way have automatically the property that the arrow in the third component is cartesian (both $k$ and $u$ are taken to be cartesian). Now, by inductively applying the argument starting from one of the extremes of the zig-zag connecting the two given objects, we are eventually led to an arrow in the category ${\cal B}^{y_{\cal D}(h)}_{(c, x)}$ under $d$ between the object at the other extreme of the zig-sag and an object in the image of the canonical functor $(d\downarrow a^{y_{\cal D}(h)}_{(c, x)}) \to (d\downarrow b^{y_{\cal D}(h)}_{(c, x)})$, whose arrow in the third component is cartesian. Now, similarly to the proof of Lemma \ref{lemmacartesianrelmono}(iii), the cartesianness of the arrows in the third components of these two objects ensures that the arrow in ${\cal B}^{y_{\cal D}(h)}_{(c, x)}$ actually lifts uniquely to an arrow in ${\cal A}^{y_{\cal D}(h)}_{(c, x)}$ satisfying the required commutativity conditions. This completes the lift of the zig-zag and hence our proof.
\end{proofs}

\begin{proofs}
	The proof is a straightforward consequence of the following easy-to-prove fact: any object $[x:X\to A]$ of ${\cal E}\slash A$ can be canonically identified, via the monomorphism $[x]\mono U_{A}^{\ast}(X)$ given by the arrow $<x, 1_{X}>:X\to A\times X$, with the equalizer of the arrows $U_{A}^{\ast}(x), \Delta_{A}\circ !_{U_{A}^{\ast}(X)}:U_{A}^{\ast}(X) \doublerightarrow{}{}   U_{A}^{\ast}(A)$, where $\Delta_{A}:1_{{\cal E}\slash A}\to U_{A}^{\ast}(A)$ is the arrow given by the diagonal $A\to A\times A$ on $A$ and $!_{U_{A}^{\ast}(X)}$ is the unique arrow $U_{A}^{\ast}(X) \to 1_{{\cal E}\slash A}$. The details are straightforward and left to the reader.
\end{proofs}

\begin{remark}\label{remlemmaslice}
	For any geometric morphisms $g:{\cal F}\to {\cal E}\slash A$, $g':{\cal F}'\to {\cal E}\slash A$ and $h:{\cal F}'\to {\cal F}$ such that $g\circ h\cong g'$, we have $\alpha_{g'}=h^{\ast}(\alpha_{g})$. In particular, for any composable geometric morphisms $g$ and $h$, we have
	\[
	\alpha_{g\circ h}=h^{\ast}(\alpha_{g}).
	\] 
\end{remark}

The following result is a generalization and a strengthening of Lemma C3.3.4 \cite{El}:

\begin{proofs}
Since $g$ is a local homeomorphism, we can suppose it to be of the form $U_{A}:{\cal H}\slash A \to {\cal H}$ for some object $A$ of $\cal H$. By Lemma \ref{lemmaslicetoposclassification}, the geometric morphism $m$ corresponds to an arrow $\alpha:1_{\cal F}\to (g\circ m)^{\ast}(A)\cong (n\circ f)^{\ast}(A)=f^{\ast}(n^{\ast}(A))$. Again by the Lemma, giving a geometric morphism $k:{\cal E}\to {\cal G}$ such that $g\circ k\cong n$ corresponds to giving an arrow $\beta:1_{\cal E}\to n^{\ast}(A)$ in $\cal E$. By Remark \ref{remlemmaslice}, the commutativity condition $k\circ f\cong m$ can be formulated in terms of pairs corresponding to these morphisms via Lemma \ref{lemmaslicetoposclassification} as the condition $f^{\ast}(\beta)=\alpha$. We thus have to show that there is exactly one arrow $\beta:1_{\cal E}\to n^{\ast}(A)$ such that $f^{\ast}(\beta)=\alpha$. If we apply the functor $f_{!}$ to the equality $f^{\ast}(\beta)=\alpha$, we obtain the equality $f_{!}(f^{\ast}(\beta))=f_{!}(\alpha)$. But the naturality of the counit $\epsilon$ of the adjunction between $f^{\ast}$ and $f_{!}$ implies the commutativity of the diagram
  \begin{equation*}
  \begin{tikzcd}
  f_{!}(f^{\ast}(1_{\cal E})) \arrow[rr, "f_{!}(f^{\ast}(\beta))"]   \arrow[d, "\epsilon_{1_{\cal E}}"]   & &  f_{!}(f^{\ast}(n^{\ast}(A))  \arrow[d, "\epsilon_{n^{\ast}(A)}"]  \\
  1_{\cal E} \ar[rr, "\beta"] & & n^{\ast}(A),   
  \end{tikzcd}
  \end{equation*} 
which forces, since $f_{!}(f^{\ast}(1_{\cal E}))=1_{\cal E}$ and $\epsilon_{1_{\cal E}}=1_{1_{\cal E}}$ by the terminal connectedness of $f$, $\beta$ to be equal to the arrow $\epsilon_{n^{\ast}(A)}\circ f_{!}(f^{\ast}(\beta))$, in other words to the transpose $1_{\cal E}=f_{!}(1_{\cal E})\to n^{\ast}(A)$ of the arrow $\alpha$.
\end{proofs}

The following result generalizes Proposition C3.3.5 \cite{El}.

\begin{proofs}
	Straightforward and left to the reader.
\end{proofs}

Given a functor $F:{\cal C}\to {\cal D}$, we can associate with it, as in Proposition \ref{propadjunctiondiscrete}, the $K$-sheaf 
$F_{K}=\textup{colim}_{\Sh({\cal D}, K)}(l'\circ F).$

Note that there is a canonical functor $\xi^{F}_{K}:{\cal C}\to {\int F_{K}}$ such that $\pi_{F_{K}}\circ \xi^{F}_{K}=F$ (which assigns to each object $c$ of $\cal C$ the element of $F_{K}$ corresponding to the colimit arrow $l'(F(c))\to F_{K}$ indexed by the object $c$). As we shall see below, the functor $\xi^{F}_{K}$ is $M^{F_{K}}_{K}$-cofinal. This motivates the following 

\begin{definition}
Let $F:{\cal C}\to {\cal D}$ be a functor and $K$ a Grothendieck topology  on $\cal D$. The \emph{$K$-comprehensive factorization of $F$} is given by the composite $F_{K}\circ \xi^{F}_{K}$:
\begin{equation*}
\begin{tikzcd}
{\cal C} \arrow[rr, "F"]   \arrow[dr, "\xi^{F}_{K}"]   & &  {\cal D}           \\
&  \int F_{K} \ar[ur, "\pi_{F_{K}}"] &  
\end{tikzcd}
\end{equation*}	
\end{definition}

\begin{proofs}
Since $p$ is $J'$-glueing, by Proposition \ref{propadjunctiondiscrete} giving a functor $G:{\cal C}\to {\cal B}$ such that $p\circ G\cong v$ amounts precisely to giving	an arrow $$\textup{colim}_{\Sh({\cal C}', J')}(l_{{\cal C}'}\circ v) \to P_{p},$$ where $P_{p}$ is the $J'$-sheaf corresponding to $p$ as in the proposition. 

By Proposition \ref{propcontinuitycofinality},
\[
\textup{colim}_{\Sh({\cal C}', J')}(l_{{\cal C}'}\circ v)\cong \textup{colim}_{\Sh({\cal C}', J')}(l_{{\cal C}'}\circ v\circ F)=\textup{colim}_{\Sh({\cal C}', J')}(l_{{\cal C}'}\circ p\circ u),
\] 
and we clearly have an arrow 
\[
\textup{colim}_{\Sh({\cal C}', J')}(l_{{\cal C}'}\circ p\circ u)\to \textup{colim}_{\Sh({\cal C}', J')}(l_{{\cal C}'}\circ p)=P_{p}
\]
induced by $u$, so by composition we obtain an arrow
\[
\textup{colim}_{\Sh({\cal C}', J')}(l_{{\cal C}'}\circ v) \to P_{p}.
\]

It is immediate to see, by exploiting the adjunction of  Proposition \ref{propadjunctiondiscrete}, that the functor $G$ corresponding to it satisfies, besides the condition $p\circ G\cong v$, the relation $G\circ F\cong u$.  

It remains to show the uniqueness (up to isomorphism) of a functor $G$ making the two triangles commute. This can be deduced from the ($2$-)universal property of the comma construction, noticing that for any  discrete fibration $p:{\cal B}\to {\cal C}'$ associated with a presheaf $P_{p}$ on ${\cal C}'$, the following diagram, where $\textbf{1}$ is the category with one object and one morphism and $\ast$ is the functor sending this object to the singleton $1_{\Set}$, is a comma square in $\textbf{Cat}$:
\begin{equation*}
\begin{tikzcd}
{\cal B}^{\textup{op}} \arrow[rr, "p^{\textup{op}}"]   \arrow[d]   & &  {{\cal C}'}^{\textup{op}} \arrow[d, "P_{p}"] \\
\textbf{1} \ar[rr, "\ast"] & & \Set.   
\end{tikzcd}
\end{equation*}

Indeed, $p^{\textup{op}}:{\cal B}^{\textup{op}}\to {{\cal C}'}^{\textup{op}}$ is isomorphic to ${\pi_{P_{p}}}^{\textup{op}}: {\int P_{p}}^{\textup{op}}\to {{\cal C}'}^{\textup{op}}$, which is in turn isomorphic to the opposite of the canonical projection functor $(\ast \downarrow P_{p})\to {\cal C}'$ (cf. the proof of Theorem 4 \cite{RossWalters}). From this universal property and the fact that $p$ (equivalently, $p^{\textup{op}}$) reflects isomorphisms, it thus follows that for any category ${\cal Z}$ and any functors $Z_{1}, Z_{2}:{\cal Z} \to {\cal B}^{\textup{op}}$, if there is an isomorphism $\chi:p^{\textup{op}}\circ Z_{1}\cong p^{\textup{op}}\circ Z_{2}$ such that $P_{p}\chi$ is the identity natural transformation on the functor $\ast \circ !_{\cal Z}$, where $!_{\cal Z}$ is the unique functor ${\cal Z}\to \textbf{1}$, then $Z_{1}$ and $Z_{2}$ are naturally isomorphic.   
\end{proofs} 

\begin{remark}
	If $J$ and $J'$ are the trivial Grothendieck topologies then the orthogonality property of Proposition \ref{proporthogonality} specializes to the well-known orthogonality property of cofinal functors with respect to discrete fibrations, first established (in the dual form of initial functors and discrete $0$-fibrations) in \cite{RossWalters}.
\end{remark}

\begin{proofs}
Conditions (i) for $F$ is clearly equivalent to condition (i) in the definition of a dense morphism of sites for the functor $l'\circ F$.

Let us now reformulate condition (ii) in the definition of a dense morphism of sites for the functor $l'\circ F$, namely the condition that for every object $d$ of $\cal D$ there exists an epimorphic family of arrows  $\{l'(F(c_{i}))\to l'(d) \mid i\in I\}$ whose domains are objects in the image of the functor $l'\circ F$. Our thesis thus immediately follows from the description of such arrows provided by Proposition \ref{propexplicit}. 

Let us show that we can reformulate condition (iii) in the definition of a dense morphism of sites for the functor $l'\circ F$ as property (iii) of the proposition. For any arrow $\xi:l'(F(x))\to l'(F(y))$ in $\Sh({\cal D}, K)$, by Proposition \ref{propexplicit} there exists a $K$-covering sieve $\{h:\textup{dom}(h)\to F(x) \mid h\in U \}$ and for each $h\in U$ an arrow $g_{h}:\textup{dom}(h)\to F(y)$ such that $\xi \circ l'(h)=l'(g_{h})$ for each $h$ and $g_{h\circ k}\equiv_{K} g_{h}\circ k$ for any arrow $k$ composable with $h$. The existence of a $J$-covering family of arrows $f_{i}:x_{i}\to x$ and a family of arrows $k_{i}:x_{i}\to y$ such that $\xi\circ l'(F(f_{i}))=l'(k_{i})$ for each $i$ can be reformulated in terms of the arrows $h$ and $g_{h}$, as follows. Let us consider, for each $i\in I$ and $h\in U$, the following pullback square:
$$
 \xymatrix{
 	P_{i, h} \ar[rd]^{e_{i, h}} \ar[r]^{\pi^{1}_{i,h}\,\,\,\,\,\,\,} \ar[d]_{\pi^{2}_{i,h}} & l'(F(x_{i})) \ar[d]^{l'(F(f_{i}))} \\
 	l'(\textup{dom}(h)) \ar[r]^{l'(h)} & l'(F(x))
 } 
$$      	

It is easy to see (cf. Proposition \ref{proplifttosite}) that the collection ${\cal F}_{i,h}$ of arrows $\chi:l'(c)\to P_{i, h}$ such that both $\pi^{1}_{i,h}\circ \chi$ and $\pi^{2}_{i,h}\circ \chi$ are images $l'(w):l'(c)\to l'(F(x_{i}))$ and $l'(z):l'(c)\to l'(\textup{dom}(h))$ under $l'$ of arrows $w$ and $z$ in $\cal D$ (where $c$ varies among the objects of $\cal C$) is epimorphic. At the cost of composing with another covering family on $l'(c)$, we can suppose that $F(f_{i})\circ w=h\circ z$ without loss of generality. Therefore, since for any $i\in I$ the collection of arrows $\{\pi^{1}_{i,h}\circ \chi \mid h\in U, \chi\in {\cal F}_{i,h}\}$ is epimorphic, $\xi\circ l'(F(f_{i}))=l'(k_{i})$ if and only if for any $h\in U$ and arrows $w$ and $z$ such that $F(f_{i})\circ w=h\circ z$, $\xi\circ e_{i,h}\circ \chi=l'(k_{i})\circ \pi^{1}_{i,h}\circ \chi$. But $\pi^{1}_{i,h}\circ \chi=l'(w)$ and $\xi\circ e_{i,h}\circ \chi=\xi \circ l'(h)\circ \pi^{2}_{i,h}\circ \chi=l'(g_{h})\circ l'(z)$. So the condition $\xi\circ l'(F(f_{i}))=l'(k_{i})$ is equivalent to the condition $g_{h}\circ z\equiv_{K} k_{i}\circ w$ for every arrow $h\in U$ and arrows $w$ and $z$ such that $F(f_{i})\circ w=h\circ z$.     

\end{proofs}



\begin{remark}
		Condition (iv) in the definition of dense morphism of sites (cf. Remark \ref{remmorphismsofsitesfaithfulness}) for the functor $l'\circ F$ admits the following reformulation in terms of $F$:

		\begin{enumerate}[(i)]
			\item[(iv)] For any arrows $f_{1}, f_{2}:c_{1}\to c_{2}$ in $\cal C$ such that $F(f_1)\equiv_{K} F(f_2)$ there exists a $J$-covering family of arrows $k_{i}:c'_{i}\to c_{1}$ such that $f_1 \circ k_{i}=f_{2}\circ k_{i}$ for all $i$.
		\end{enumerate}

		If a functor $F$ satisfies the conditions of Proposition \ref{propweaklydensemorphism} plus condition (iv) then $l'\circ F$ is a dense morphism of sites and hence $F:({\cal C}, J)\to ({\cal D}, K)$ is a weakly dense morphism of sites (cf. Remark \ref{remmorphismsofsites}(a)).  	
\end{remark}	

Summarizing, we have the following result:

\begin{proofs}
Since $\Sh(l'\circ F)$ is the composite of $\Sh(F)$ with the canonical equivalence $\Sh(a_{K}({\cal D}), C_{K}^{\cal D})\simeq \Sh({\cal D}, K)$ and the site $(a_{K}({\cal D}), C_{K}^{\cal D})$ is subcanonical, the direction (ii) $\Rightarrow$ (i) follows from Theorem 11.8 \cite{Shulman}. The equivalence between (ii) and (iii) follows by definition of a  weakly dense morphism of sites (in light of Proposition \ref{propweaklydensemorphism}). Lastly, the implication (i) $\Rightarrow$ (ii) follows from Proposition \ref{propdensitysubcanonical}. 	
\end{proofs}

\begin{remark}
	Theorem \ref{thmweakdensityequivalence} constitutes a vast generalization of Grothendieck's Comparison Lemma (Theorem 4.1 from section III of \cite{grothendieck}).
