	$$
	\xymatrix{
		\Sh({\cal D}, K) \ar[rr]^{C_{F}} \ar[d] & & \Sh({\cal C}, J) \ar[d] \\
		[{\cal D}^{\textup{op}}, \Set] \ar[rr]^{E(F)} & &  [{\cal C}^{\textup{op}}, \Set], 
	}
	$$
	where $E(F)$ is the geometric morphism induced by $F$ (regarded as a comorphism of trivial sites) and the vertical arrows are the canonical geometric inclusions. Let $\Sh(F):\Sh({\cal C}, J) \to \Sh({\cal D}, K)$ be the geometric morphism induced by $F$ as a morphism of sites $({\cal D}, K)\to ({\cal C}, J)$. Since $F$ is $J$-dense and has the covering-lifting property, by Proposition \ref{proprecoverytopology}, $J=K^{F}$ and hence, by Lemma \ref{lemmafullfaithfulcoverreflecting}, $F$ is cover-reflecting. So $F$ is a dense morphism of sites (cf. Remark \ref{remmorphismsofsitesfaithfulness}) and hence $\Sh(F)$ is an equivalence. To prove that $g$ is a quasi-inverse to $C_{F}$, it is clearly enough to show that $C_{F}^{\ast}\circ {\Sh(F)}^{\ast}\circ l_{\cal D}\cong l_{\cal D}$. Now, $\Sh(F)^{\ast}\circ l_{\cal D}\cong l_{\cal C}\circ F$, so $C_{F}^{\ast}\circ {\Sh(F)}^{\ast}\circ l_{\cal D}\cong C_{F}^{\ast}\circ l_{\cal C}\circ F$. But $C_{F}^{\ast}\circ  l_{\cal C}\cong C_{F}^{\ast} \circ a_{J}\circ y_{\cal C}\cong a_{K}\circ E(F)^{\ast}\circ y_{\cal C}$, where the second isomorphism follows from the commutativity of the above square. Now, by Proposition \ref{proplocalfullnessandfaithfulness}, since $F$ is $K$-full and $K$-faithful, the canonical arrow $l_{\cal D}\cong a_{K}\circ y_{\cal D} \to a_{K}\circ E(F)^{\ast}\circ y_{\cal C}\circ F$ is an isomorphism, so $C_{F}^{\ast}\circ g^{\ast}\circ l_{\cal D}\cong l_{\cal D}$, as required.  
\end{proofs}

\begin{remark}
	For a comorhism of sites $F:({\cal D}, K)\to ({\cal C}, J)$ to induce an equivalence $C_{F}$ it is necessary that $F$ be $J$-dense (by Proposition \ref{propsurjectioncomorphismofsites}). So inducing an equivalence is not a sufficient condition on a morphism of sites  $F:({\cal D}, K)\to ({\cal C}, J)$ for it to be also a comorphism between the same sites (since there are weakly dense morphisms which are not dense); in fact, this is the case if and only if $F$ is $J$-dense and $K$-full (cf. Corollary \ref{corequivalencecovliftproperty}). 
\end{remark}

